mapper.select:
SELECT COALESCE(SUM(duration), 0)
FROM time_entry
WHERE issue_id = #{issueId}

SELECT t.id, t.issue_id, t.user_id, t.work_date, t.duration, t.start_time, t.description, t.created_at, t.updated_at, i.issue_key, i.title AS issue_title, wiav.name AS work_type, wiav.id AS work_type_id, wiav.color AS work_type_color FROM time_entry t LEFT JOIN issue i ON i.id = t.issue_id LEFT JOIN time_entry_attribute_value teav ON teav.time_entry_id = t.id AND teav.attribute_id = 1 LEFT JOIN work_item_attribute_value wiav ON wiav.id = teav.value_id WHERE t.user_id = #{userId} AND t.work_date >= #{startDate}::date AND t.work_date <= #{endDate}::date
AND i.project_id = #{projectId}
AND teav.value_id = #{activityId}
ORDER BY t.work_date ASC, t.start_time ASC, t.created_at ASC
